from django.db import migrations, models

# The crops the system already treated as tree crops (the parcel form's perennial list); every other crop starts as "Seed".
# Names are matched on their first word, so "Banana (Saging)" and "Cacao" both count. Crop Settings can change any of them.
TREE_FIRST_WORDS = ('mango', 'cacao', 'banana', 'coffee')


def mark_tree_crops(apps, schema_editor):
    CropType = apps.get_model('production', 'CropType')
    for crop in CropType.objects.all():
        name = (crop.name or '').strip().lower()
        if name.split(' ')[0] in TREE_FIRST_WORDS or name == 'other fruits':
            crop.planting_type = 'Tree'
            crop.save(update_fields=['planting_type'])


class Migration(migrations.Migration):

    dependencies = [
        ('production', '0064_crop_land_owner_and_planting_material'),
    ]

    operations = [
        migrations.AddField(
            model_name='croptype',
            name='planting_type',
            field=models.CharField(choices=[('Seed', 'Seed'), ('Tree', 'Tree'), ('Both', 'Seed or Tree')], default='Seed', max_length=10),
        ),
        migrations.RunPython(mark_tree_crops, migrations.RunPython.noop),
    ]
